mapper.select:
SELECT 
FROM TBL_INVESTMENT_PLAN
WHERE DELETE_FLAG = 0

    AND PLAN_NO LIKE CONCAT('%', #{planNo}, '%')


    AND PLAN_NAME LIKE CONCAT('%', #{planName}, '%')


    AND INVESTMENT_TYPE = #{investmentType}


    AND RISK_LEVEL = #{riskLevel}


    AND PLAN_STATUS = #{planStatus}


    AND COMPANY_ID = #{companyId}

ORDER BY CREATED_TIME DESC

mapper.update:
UPDATE TBL_INVESTMENT_PLAN
SET PLAN_STATUS = #{planStatus}, UPDATED_TIME = CURRENT_TIMESTAMP
WHERE PLAN_ID = #{planId}

UPDATE TBL_INVESTMENT_PLAN
SET ACTUAL_RETURN_RATE = #{actualReturnRate}, UPDATED_TIME = CURRENT_TIMESTAMP
WHERE PLAN_ID = #{planId}
